import { Group, Mesh, PlaneGeometry, MeshStandardNodeMaterial, MeshBasicNodeMaterial, Color, Fog } from 'three/webgpu';
import { uv, mix, vec3 } from 'three/tsl';
import { gsap } from 'gsap';

/**
 * @param {any} config
 * @param {any} ctx
 * @returns {THREE.Object3D}
 */
export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, MeshStandardNodeMaterial, MeshBasicNodeMaterial, Color, Fog } = ctx.THREE;

  const root = new Group();

  // -----------------------------------------------------------------
  // 1️⃣ Backdrop plane with vertical gradient
  // -----------------------------------------------------------------
  const backdropGeo = new PlaneGeometry(7, 6);
  const gradientStops = (config.visualSpec?.colors?.gradientStops) || [
    { at: 0, hex: '#0b0b10' },
    { at: 0.65, hex: '#101017' },
    { at: 1, hex: '#16161d' }
  ];
  // Simple 2‑stop gradient (first → last)
  const startColor = new Color(gradientStops[0].hex);
  const endColor = new Color(gradientStops[gradientStops.length - 1].hex);
  const backdropMat = new MeshStandardNodeMaterial();
  backdropMat.colorNode = mix(vec3(startColor), vec3(endColor), uv().y);
  backdropMat.roughness = 1;
  backdropMat.metalness = 0;
  const backdrop = new Mesh(backdropGeo, backdropMat);
  backdrop.position.set(0, 0, -3);
  root.add(backdrop);

  // -----------------------------------------------------------------
  // 2️⃣ Load GLB (primary & secondary gear, jewel, shafts)
  // -----------------------------------------------------------------
  if (config.meshUrl) {
    ctx.glbLoader.loadGLB(config.meshUrl).then((gltf) => {
      // The GLB already contains the correct hierarchy & materials.
      // Center it (already normalized) and add to root.
      root.add(gltf.scene);
    });
  }

  // -----------------------------------------------------------------
  // 3️⃣ Contact shadow ellipse (simple semi‑transparent plane)
  // -----------------------------------------------------------------
  const shadowGeo = new PlaneGeometry(2.6, 1.2);
  const shadowMat = new MeshBasicNodeMaterial({
    color: new Color(config.visualSpec?.colors?.surface || '#14141a'),
    transparent: true,
    opacity: 0.5,
    depthWrite: false
  });
  const shadow = new Mesh(shadowGeo, shadowMat);
  shadow.rotation.x = -Math.PI / 2; // face upward
  shadow.position.set(0, -1.2, 0);
  root.add(shadow);

  // -----------------------------------------------------------------
  // 4️⃣ Text (headline & caption) via font atlas
  // -----------------------------------------------------------------
  const textItems = config.textContent ??
    config.intent?.visualSpec?.textContent ??
    [];

  for (const item of textItems) {
    const opts = {
      fontSize: item.typography?.fontSize ?? (item.role === 'headline' ? 68 : 18),
      color: config.visualSpec?.colors?.ink || '#16161d',
      align: 'center',
      letterSpacingPx: item.typography?.letterSpacing ? item.typography.letterSpacing * item.typography.fontSize : 0
    };
    const textObj = ctx.fontAtlas.createText(item.text, opts);
    // Position based on role
    if (item.role === 'headline') {
      textObj.position.set(0, -1.7, 0);
    } else if (item.role === 'caption') {
      textObj.position.set(0, -2.1, 0);
    }
    root.add(textObj);
  }

  // -----------------------------------------------------------------
  // 5️⃣ Fog (optional – adds depth hint)
  // -----------------------------------------------------------------
  const fogColor = new Color(config.visualSpec?.colors?.background || '#0b0b10');
  root.fog = new Fog(fogColor, 5, 11);

  // -----------------------------------------------------------------
  // 6️⃣ Cinematic primitive: orbit (camera drift simulated on root)
  // -----------------------------------------------------------------
  const primitives = [];
  if (config.cinematicPrimitives) {
    for (const prim of config.cinematicPrimitives) {
      const fn = ctx.primitives[prim.name];
      if (fn) {
        const instance = fn(root, prim.params ?? {});
        primitives.push(instance);
      }
    }
  }

  // -----------------------------------------------------------------
  // 7️⃣ Cleanup
  // -----------------------------------------------------------------
  root.userData.cleanup = () => {
    // Dispose geometries & materials created here
    backdropGeo.dispose();
    backdropMat.dispose();
    shadowGeo.dispose();
    shadowMat.dispose();

    // Cleanup loaded GLB (if needed)
    // Assume GLTF.dispose() pattern if present
    // (the loader may already handle caching)

    // Cleanup primitives
    for (const p of primitives) {
      if (p && typeof p.cleanup === 'function') p.cleanup();
    }

    // Kill any GSAP timelines (none currently, but safe guard)
    gsap.globalTimeline.clear();
  };

  // -----------------------------------------------------------------
  // 8️⃣ Event handlers placeholder (none for this spec)
  // -----------------------------------------------------------------
  root.userData.handlers = {};

  return root;
}
